from hypothesis import strategies as st


def _parse(inp):
    lines = [l for l in inp.split("\n") if l.strip()]
    e1 = json.loads(lines[0])
    e2 = json.loads(lines[1])
    return e1, e2


def _is_tree(k, edges):
    if len(edges) != k - 1:
        return False
    adj = [[] for _ in range(k)]
    for e in edges:
        if not (isinstance(e, list) and len(e) == 2):
            return False
        a, b = e
        if not (isinstance(a, int) and isinstance(b, int)):
            return False
        if not (0 <= a < k and 0 <= b < k):
            return False
        adj[a].append(b)
        adj[b].append(a)
    seen = [False] * k
    seen[0] = True
    stack = [0]
    cnt = 1
    while stack:
        u = stack.pop()
        for v in adj[u]:
            if not seen[v]:
                seen[v] = True
                cnt += 1
                stack.append(v)
    return cnt == k


@st.composite
def gen(draw):
    def rand_tree(k):
        edges = []
        for i in range(1, k):
            p = draw(st.integers(0, i - 1))
            edges.append((p, i))
        perm = draw(st.permutations(list(range(k))))
        out = []
        for a, b in edges:
            a, b = perm[a], perm[b]
            if draw(st.booleans()):
                a, b = b, a
            out.append([a, b])
        out = draw(st.permutations(out)) if out else out
        return [list(e) for e in out]

    n = draw(st.integers(1, 7))
    m = draw(st.integers(1, 7))
    e1 = rand_tree(n)
    e2 = rand_tree(m)
    return json.dumps(e1) + "\n" + json.dumps(e2) + "\n"


