        e1, e2 = _parse(inp)
    except Exception:
        return False
    if not (isinstance(e1, list) and isinstance(e2, list)):
        return False
    n = len(e1) + 1
    m = len(e2) + 1
    if not (1 <= n <= 10**5 and 1 <= m <= 10**5):
        return False
    return _is_tree(n, e1) and _is_tree(m, e2)


def _bfs(adj, src):
    dist = [-1] * len(adj)
    dist[src] = 0
    dq = deque([src])
    while dq:
        u = dq.popleft()
        for v in adj[u]:
            if dist[v] < 0:
                dist[v] = dist[u] + 1
                dq.append(v)
    return dist


def _diameter(N, edges):
    adj = [[] for _ in range(N)]
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)
    d0 = _bfs(adj, 0)
    far = max(range(N), key=lambda i: d0[i])
    d1 = _bfs(adj, far)
    return max(d1)


